def count_divisors_sq(x):
    d_x2 = 1
    temp_x = x
    d = 2
    while d * d <= temp_x:
        if temp_x % d == 0:
            count = 0
            while temp_x % d == 0:
                count += 1
                temp_x //= d
            d_x2 *= (2 * count + 1)
        d += 1
    if temp_x > 1:
        d_x2 *= (2 * 1 + 1)
    return d_x2

